<?php
namespace App\Http\Controllers\Admin; use App\Http\Controllers\Controller; use App\Models\{Site,AdSlot}; use Illuminate\Http\Request;
class SiteController extends Controller { public function index(){return view('admin.sites.index',['sites'=>Site::withCount('articles')->orderBy('name')->get()]);} public function create(){return view('admin.sites.form',['site'=>new Site(['active'=>true])]);} public function store(Request $r){$d=$this->v($r);$d['active']=$r->boolean('active');$d['gam_enabled']=$r->boolean('gam_enabled');$s=Site::create($d);foreach(['banner_top'=>'Top banner','banner_mid'=>'Middle banner','banner_bot'=>'Bottom banner','anchor'=>'Anchor','interstitial'=>'Interstitial','rewarded'=>'Rewarded'] as $k=>$l)AdSlot::firstOrCreate(['site_id'=>$s->id,'key'=>$k],['label'=>$l,'type'=>in_array($k,['anchor','interstitial','rewarded'])?$k:'display','enabled'=>false]);return redirect()->route('admin.sites.edit',$s)->with('ok','Site created with default ad slots.');} public function edit(Site $site){return view('admin.sites.form',compact('site'));} public function update(Request $r,Site $site){$d=$this->v($r);$d['active']=$r->boolean('active');$d['gam_enabled']=$r->boolean('gam_enabled');$site->update($d);return back()->with('ok','Site saved.');} public function destroy(Site $site){$site->delete();return back()->with('ok','Site deleted.');} private function v(Request $r){return $r->validate(['name'=>'required|string|max:255','domain'=>'nullable|string|max:255|unique:sites,domain,'.($r->route('site')?->id??'NULL'),'tagline'=>'nullable|string|max:255','contact_email'=>'nullable|email|max:255','gam_network_id'=>'nullable|string|max:100','gtm_container_id'=>'nullable|string|max:100','ga4_measurement_id'=>'nullable|string|max:100','ads_txt'=>'nullable|string','active'=>'nullable|boolean','gam_enabled'=>'nullable|boolean']);} }
